    "http://localhost:8000/api/contact" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "name=Hakan Kekec"\
    --form "email=hakan@example.com"\
    --form "subject=Bilgi talebi"\
    --form "category=general"\
    --form "project_id=1"\
    --form "message=Merhaba, bilgi almak istiyorum."\
    --form "attachment=@C:\Users\kresc\AppData\Local\Temp\php6363.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/contact"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('name', 'Hakan Kekec');
body.append('email', 'hakan@example.com');
body.append('subject', 'Bilgi talebi');
body.append('category', 'general');
body.append('project_id', '1');
body.append('message', 'Merhaba, bilgi almak istiyorum.');
body.append('attachment', document.querySelector('input[name="attachment"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

