    --header "Accept: application/json" \
    --data "{
    \"counselor_id\": 2,
    \"room_id\": 1,
    \"start_at\": \"2026-07-01 10:00:00\",
    \"end_at\": \"2026-07-01 10:30:00\",
    \"notes\": \"Ilk gorusme talebi.\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
