    --get "http://localhost:8000/api/panel/requests/export?status=completed&amp;type=vehicle&amp;project_id=1&amp;period_id=1&amp;format=csv" \
    --header "Authorization: Bearer {YOUR_ACCESS_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"project_id\": 17,
    \"period_id\": 17
}"
</code></pre></div>


