    --header "Accept: application/json" \
    --data "{
    \"title\": \"Guncel duyuru\",
    \"content\": \"Guncellenen duyuru metni.\",
    \"category\": \"general\",
    \"target_roles\": [
        \"student\",
        \"alumni\"
    ],
    \"target_units\": [
